   "@type": "Question",
   "name": "What does healthy dog poop look like?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Chocolate brown, moist but firm enough to hold its shape when you pick it up."
   }
  },
  {
   "@type": "Question",
   "name": "Is gray or white dog poop a problem?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Gray or white poop can point to a bile or pancreas problem, so a vet visit is recommended. If you see white, rice-like bits, ask for a worm test."
   }
  },
  {
   "@type": "Question",
   "name": "What should I do if I see bloody or black poop?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Bloody poop or sticky black poop can be a sign of bleeding, so contact your vet right away."
   }
  },
  {
   "@type": "Question",
   "name": "My dog had diarrhea once. Do I need a vet?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "If it's once or twice and your dog is eating and playing normally, many owners watch for about a day. If it lasts more than a day, has blood, or comes with vomiting, see a vet."
   }
  }
